using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;
using UnityEditor;

namespace C01.Ship.V5.Editor {
    public static class ShipV5Validation {
        [Serializable] public class Route {public string zone,status;public Vector3[] corners;public float sampleDistance;}
        [Serializable] public class Report {public string status,unityVersion;public int placements,meshParts,colliders,collisionCandidates,penetrations,coverageRays,clearanceRays,importedModels,reachableZones,transportLinks;public List<string> errors=new List<string>();public List<Route> routes=new List<Route>();}
        public static GameObject Master()=>GameObject.Find(ShipV5Builder.MasterName);
        static bool Near(Vector3 a,Vector3 b,float tolerance=.001f)=>Vector3.Distance(a,b)<=tolerance;
        static string Owner(Collider c)=>c.GetComponentInParent<ShipInstanceV5>()?.placementId+"/"+c.name;
        // Geometry-only pose audit. Restore controller ownership immediately; normal runtime safety is untouched.
        public static void GeometryPose(ShipGateV5 gate,float value){var air=gate.interlockAirlock;var lift=gate.interlockLift;try{gate.interlockAirlock=null;gate.interlockLift=null;gate.SetImmediate(value);}finally{gate.interlockAirlock=air;gate.interlockLift=lift;}}
        [MenuItem("Tools/C01 Ship v5/Validate")]
        public static void Run()=>Run("unity_v5_qa.json",true);
        public static Report Run(string reportFile,bool exhaustive=true) {
            Directory.CreateDirectory(ShipV5Builder.QA);var r=new Report{unityVersion=Application.unityVersion};
            void Check(bool ok,string message){if(!ok)r.errors.Add(message);}
            var root=Master();var data=ShipV5Builder.Read();
            if(root==null){r.errors.Add("Ship master missing");Finish(r,reportFile);return r;}
            var gates=root.GetComponentsInChildren<ShipGateV5>(true);var lifts=root.GetComponentsInChildren<ShipLiftV5>(true);
            var gateValues=gates.Select(g=>g.openness).ToArray();var gateTargets=gates.Select(g=>g.target).ToArray();
            var liftFloors=lifts.Select(l=>l.currentFloor).ToArray();var liftTargets=lifts.Select(l=>l.targetFloor).ToArray();var carPositions=lifts.Select(l=>l.car.position).ToArray();
            try {
                foreach(var l in lifts)l.ResetToFloor(1);foreach(var g in gates)g.SetImmediate(0);Physics.SyncTransforms();
                var instances=root.GetComponentsInChildren<ShipInstanceV5>(true);r.placements=instances.Length;Check(instances.Length==data.placements.Length,"Placement count");
                var byId=instances.GroupBy(i=>i.placementId).ToDictionary(g=>g.Key,g=>g.ToArray());var models=data.models.ToDictionary(m=>m.id);
                foreach(var p in data.placements){if(!byId.TryGetValue(p.id,out var found)||found.Length!=1){Check(false,"Missing/duplicate placement "+p.id);continue;}var inst=found[0];
                    Check(inst.modelId==p.model&&inst.category==p.category&&inst.zoneId==p.zone&&inst.deck==p.deck,"Placement metadata "+p.id);
                    Check(Near(inst.transform.position,new Vector3(p.x,p.y,p.z))&&Quaternion.Angle(inst.transform.rotation,Quaternion.Euler(0,p.yaw,0))<.001f&&Near(inst.transform.lossyScale,Vector3.one),"Placement transform "+p.id);
                    Check(PrefabUtility.IsPartOfPrefabInstance(inst)&&PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(inst.gameObject)==ShipV5Builder.Root+"/Prefabs/Modules/"+p.model+".prefab","Prefab linkage "+p.id);
                    var solids=inst.GetComponentsInChildren<ShipSolidV5>(true);var model=models[p.model];Check(solids.Length==model.parts.Length,"Part count "+p.id);
                    for(int index=0;index<model.parts.Length;index++){var matches=solids.Where(s=>s.partIndex==index&&s.modelId==p.model).ToArray();Check(matches.Length==1,"Part identity "+p.id+"/"+index);if(matches.Length!=1)continue;var s=matches[0];var part=model.parts[index];r.meshParts++;var filter=s.GetComponent<MeshFilter>();var renderer=s.GetComponent<MeshRenderer>();var colliders=s.GetComponents<Collider>();
                        Check(s.role==part.role&&renderer!=null&&renderer.sharedMaterial!=null,"Part renderer/role "+p.id+"/"+index);
                        Check(Near(s.transform.localPosition,Vector3.zero)&&Quaternion.Angle(s.transform.localRotation,Quaternion.identity)<.001f&&Near(s.transform.localScale,Vector3.one),"Part transform "+p.id+"/"+index);
                        var mesh=filter==null?null:filter.sharedMesh;var expected=ShipV5Builder.Bounds(part);Check(mesh!=null,"Missing mesh "+p.id+"/"+index);if(mesh==null)continue;
                        Check(Near(mesh.bounds.min,expected.min)&&Near(mesh.bounds.max,expected.max)&&mesh.triangles.Length==(4*(part.outline.Length/2)-4)*3,"Mesh bounds/triangles "+p.id+"/"+index);
                        // Bounds alone do not prove full geometry: compare the actual triangle vertex sequence.
                        var reference=ShipV5Builder.Prism(part);try{var actual=mesh.vertices;var wanted=reference.vertices;Check(actual.Length==wanted.Length&&actual.Zip(wanted,(a,b)=>Near(a,b,.0001f)).All(v=>v),"Mesh full source geometry "+p.id+"/"+index);}finally{UnityEngine.Object.DestroyImmediate(reference);}
                        Check(colliders.Length==1&&colliders[0].enabled&&!colliders[0].isTrigger,"Missing/disabled/extra collider "+p.id+"/"+index);if(colliders.Length!=1)continue;
                        if(ShipV5Builder.Rectangle(part)){var box=colliders[0] as BoxCollider;Check(box!=null&&Near(box.center,expected.center)&&Near(box.size,expected.size),"Box geometry "+p.id+"/"+index);}else{var mc=colliders[0] as MeshCollider;Check(mc!=null&&mc.convex&&mc.sharedMesh==mesh,"Convex collider geometry "+p.id+"/"+index);}
                    }
                }
                Check(instances.All(i=>data.placements.Any(p=>p.id==i.placementId)),"Unexpected placement");
                var markers=root.GetComponentsInChildren<ShipZoneV5>(true);Check(markers.Length==data.zones.Length,"Zone marker count");foreach(var z in data.zones){var found=markers.Where(m=>m.zoneId==z.id).ToArray();Check(found.Length==1,"Zone marker identity "+z.id);if(found.Length==1)Check(found[0].kind==z.kind&&found[0].deck==z.deck&&Mathf.Abs(found[0].floor-z.floor)<.001f&&Mathf.Abs(found[0].height-z.height)<.001f&&Near(found[0].transform.position,ShipV5Builder.V(z.waypoint)),"Zone marker metadata/position "+z.id);}
                foreach(var model in data.models){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(ShipV5Builder.Root+"/Prefabs/Modules/"+model.id+".prefab");Check(asset!=null&&asset.GetComponentsInChildren<ShipSolidV5>(true).Length==model.parts.Length,"Native model prefab "+model.id);if(asset==null)continue;foreach(var socket in model.sockets??Array.Empty<SocketDataV5>()){var t=asset.transform.Find(socket.name);Check(t!=null&&Near(t.localPosition,ShipV5Builder.V(socket.position))&&Vector3.Angle(t.localRotation*Vector3.forward,ShipV5Builder.V(socket.normal))<.01f&&t.GetComponents<Component>().Length==1,"Model socket "+model.id+"/"+socket.name);}}
                Content(data,instances,Check);Controls(data,root,byId,gates,lifts,Check);Coverage(data,root,r,Check);
                if(exhaustive){Collisions(root,r,Check,"closed");foreach(var g in gates)GeometryPose(g,1);Physics.SyncTransforms();Collisions(root,r,Check,"open");Navigation(root,data,r,Check);Imported(data,r,Check);}
            } catch(Exception e){r.errors.Add("Audit exception: "+e);}
            finally {for(int i=0;i<lifts.Length;i++){lifts[i].ResetToFloor(liftFloors[i]);lifts[i].car.position=carPositions[i];lifts[i].targetFloor=liftTargets[i];}for(int i=0;i<gates.Length;i++){GeometryPose(gates[i],gateValues[i]);gates[i].target=gateTargets[i];}Physics.SyncTransforms();}
            Finish(r,reportFile);return r;
        }
        static void Finish(Report r,string file){r.status=r.errors.Count==0?"PASS":"FAIL";File.WriteAllText(Path.Combine(ShipV5Builder.QA,file),JsonUtility.ToJson(r,true));if(r.errors.Count>0)throw new InvalidOperationException("C01 v5 audit FAIL ("+r.errors.Count+"): "+string.Join("\n",r.errors.Take(40)));Debug.Log("C01 v5 audit PASS: "+r.placements+" placements / "+r.meshParts+" parts / "+r.reachableZones+" routes");}
        static void Content(ShipDataV5 data,ShipInstanceV5[] instances,Action<bool,string> check){
            check(data.unit==3&&data.decks.Length==3,"Units/deck count");foreach(var pair in new[]{(0,-12.4f),(1,0f),(2,6.4f)})check(data.decks.Any(d=>d.id==pair.Item1&&Mathf.Abs(d.y-pair.Item2)<.001f),"Deck elevation "+pair.Item1);
            var cabins=data.zones.Where(z=>z.kind=="cabin").ToArray();check(cabins.Length==24,"Cabin count");check(data.zones.Count(z=>z.kind=="bathroom")==24,"Bathroom count");
            foreach(var z in data.zones){if(z.kind=="cabin"||z.kind=="corridor"||z.kind=="bathroom")check(Mathf.Abs(z.height-6)<.001f,"Clear height declaration "+z.id);if(z.kind=="sector")check(Mathf.Abs(z.height-12)<.001f,"Sector height declaration "+z.id);}
            foreach(var c in cabins){check(Mathf.Abs(c.bounds[1]-c.bounds[0]-9)<.001f&&Mathf.Abs(c.bounds[3]-c.bounds[2]-9)<.001f,"Cabin dimensions "+c.id);check(instances.Count(p=>p.zoneId==c.id&&p.modelId=="P_Bed")==4,"Four cabin beds "+c.id);check(instances.Count(p=>p.zoneId==c.id&&p.modelId=="P_Locker")==8,"Eight cabin lockers "+c.id);var bath=data.zones.SingleOrDefault(z=>z.parent==c.id&&z.kind=="bathroom");check(bath!=null&&Mathf.Abs((bath.bounds[1]-bath.bounds[0])*(bath.bounds[3]-bath.bounds[2])-18)<.001f,"Cabin bathroom "+c.id);}
            check(!instances.Any(p=>p.zoneId=="L1_GYM"&&(p.modelId=="P_Bed"||p.modelId=="P_MedBed")),"Gym beds forbidden");check(instances.Count(p=>p.zoneId=="L1_MED"&&p.modelId=="P_MedBed")==2,"Medical two beds");check(instances.Count(p=>p.category=="Engines")==5,"Five exterior engines");check(instances.Any(p=>p.modelId=="P_Shuttle"),"Escape craft");check(instances.Any(p=>p.modelId=="P_Plant"),"Hydroponic plants");check(instances.Any(p=>p.zoneId=="L0_PURIFICATION"&&p.modelId=="P_Purifier"),"Purification content");check(instances.Any(p=>p.zoneId=="L0_ENGINE_ROOM"&&p.modelId=="P_ReactorLarge"),"Lower engine machinery");
        }
        static void Controls(ShipDataV5 data,GameObject root,Dictionary<string,ShipInstanceV5[]> instances,ShipGateV5[] gates,ShipLiftV5[] lifts,Action<bool,string> check){
            check(gates.Length==data.gates.Length,"Gate count");check(lifts.Length==2,"Two lifts");var buttons=root.GetComponentsInChildren<ShipButtonV5>(true);check(buttons.Length==data.placements.Count(p=>!string.IsNullOrEmpty(p.buttonGate)||!string.IsNullOrEmpty(p.buttonLift)),"Button count");
            foreach(var p in data.placements.Where(p=>!string.IsNullOrEmpty(p.buttonGate)||!string.IsNullOrEmpty(p.buttonLift))){var found=buttons.Where(b=>b.GetComponent<ShipInstanceV5>()?.placementId==p.id).ToArray();check(found.Length==1,"Button identity "+p.id);if(found.Length==1){var b=found[0];check(b.gateId==p.buttonGate&&b.liftId==p.buttonLift&&b.floor==p.buttonFloor,"Button metadata "+p.id);if(!string.IsNullOrEmpty(p.buttonLift))check(b.lift!=null&&b.lift.id==p.buttonLift,"Button lift binding "+p.id);if(!string.IsNullOrEmpty(p.buttonGate))check(b.gate!=null&&b.gate.id==p.buttonGate&&b.airlock==b.gate.interlockAirlock,"Button gate/airlock binding "+p.id);}}
            foreach(var g in data.gates){var actual=gates.Where(a=>a.id==g.id).ToArray();check(actual.Length==1,"Gate identity "+g.id);if(actual.Length!=1)continue;var gate=actual[0];check(Near(gate.transform.position,new Vector3(g.x,g.y,g.z))&&Quaternion.Angle(gate.transform.rotation,Quaternion.Euler(0,g.yaw,0))<.001f,"Gate pose "+g.id);check(gate.leaves.Length==g.leaves.Length&&gate.leaves.Length>=8&&gate.travel.Length==g.leaves.Length,"Gate leaf segments "+g.id);for(int i=0;i<g.leaves.Length&&i<gate.leaves.Length;i++){check(gate.leaves[i]!=null&&gate.leaves[i].GetComponent<ShipInstanceV5>()?.placementId==g.leaves[i],"Gate leaf reference "+g.id+"/"+i);var p=data.placements.Single(v=>v.id==g.leaves[i]);check(Near(gate.travel[i],ShipV5Builder.V(p.travel)),"Gate travel "+g.id+"/"+i);var rb=gate.leaves[i].GetComponent<Rigidbody>();check(rb!=null&&rb.isKinematic,"Leaf kinematic body "+g.id);}
                foreach(var id in g.buttons){var b=buttons.SingleOrDefault(v=>v.GetComponent<ShipInstanceV5>()?.placementId==id);check(b!=null&&b.gate==gate&&b.gateId==g.id&&b.GetComponentInChildren<Collider>()!=null,"Gate button "+id);}
                if(!string.IsNullOrEmpty(g.airlock))check(gate.interlockAirlock!=null&&gate.interlockAirlock.name==g.airlock,"Airlock ownership "+g.id);
                if(!string.IsNullOrEmpty(g.lift))check(gate.interlockLift!=null&&gate.interlockLift.id==g.lift&&gate.landingFloor==g.floor,"Landing ownership "+g.id);
            }
            foreach(var l in data.lifts){var lift=lifts.SingleOrDefault(v=>v.id==l.id);check(lift!=null,"Lift identity "+l.id);if(lift==null)continue;check(lift.car!=null&&lift.car.name==l.car&&lift.car.GetComponent<Rigidbody>()?.isKinematic==true,"Lift car/body "+l.id);check(lift.elevations.SequenceEqual(l.elevations)&&lift.landings.Length==3&&lift.player!=null,"Lift bindings "+l.id);check(lift.footprint==new Vector4(l.bounds[0],l.bounds[1],l.bounds[2],l.bounds[3]),"Lift footprint "+l.id);for(int floor=0;floor<3;floor++){check(lift.landings[floor]!=null&&lift.landings[floor].id==l.landings[floor],"Lift landing "+l.id+"/"+floor);check(buttons.Any(b=>b.lift==lift&&b.floor==floor&&b.transform.IsChildOf(lift.car)),"Car selector "+l.id+"/"+floor);}foreach(var p in data.placements.Where(p=>p.parent==l.car))check(instances.TryGetValue(p.id,out var values)&&values.Length==1&&values[0].transform.IsChildOf(lift.car),"Car parent "+p.id);}
            var explorer=UnityEngine.Object.FindFirstObjectByType<ShipExplorerV5>();check(explorer!=null&&explorer.master==root&&explorer.view!=null&&explorer.player!=null,"Explorer scene bindings");
        }
        static void Coverage(ShipDataV5 data,GameObject root,Report r,Action<bool,string> check){
            foreach(var c in data.coverage){int n=c.poly.Length/2;var center=Vector3.zero;for(int i=0;i<n;i++)center+=new Vector3(c.poly[i*2],c.plane,c.poly[i*2+1]);center/=n;var samples=new List<Vector3>{center};for(int i=0;i<n;i++)samples.Add(Vector3.Lerp(new Vector3(c.poly[2*i],c.plane,c.poly[2*i+1]),center,.015f));var outward=c.normal=="up"?Vector3.up:Vector3.down;foreach(var p in samples){r.coverageRays++;var hits=Physics.RaycastAll(p+outward*.04f,-outward,.08f,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore);check(hits.Any(h=>h.collider.transform.IsChildOf(root.transform)&&Mathf.Abs(h.point.y-c.plane)<.001f&&Vector3.Dot(h.normal,outward)>.95f),"Coverage gap "+c.id+" @"+p);}}
            foreach(var z in data.zones){var p=ShipV5Builder.V(z.waypoint);r.clearanceRays++;var hits=Physics.RaycastAll(p+Vector3.up*.025f,Vector3.up,z.height+.2f,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(root.transform)).OrderBy(h=>h.distance).ToArray();check(hits.Length==0||hits[0].distance+.025f>=z.height-.005f,"Vertical clearance "+z.id+" actual="+(hits.Length>0?(hits[0].distance+.025f).ToString():"open sky"));}
        }
        static void Collisions(GameObject root,Report r,Action<bool,string> check,string state){
            var all=root.GetComponentsInChildren<Collider>(true);r.colliders=all.Length;var boxes=all.Select(c=>c.bounds).ToArray();var buckets=new Dictionary<Vector3Int,List<int>>();
            for(int i=0;i<all.Length;i++){var b=boxes[i];for(int x=Mathf.FloorToInt(b.min.x/3);x<=Mathf.FloorToInt(b.max.x/3);x++)for(int y=Mathf.FloorToInt(b.min.y/3);y<=Mathf.FloorToInt(b.max.y/3);y++)for(int z=Mathf.FloorToInt(b.min.z/3);z<=Mathf.FloorToInt(b.max.z/3);z++){var key=new Vector3Int(x,y,z);if(!buckets.TryGetValue(key,out var list))buckets[key]=list=new List<int>();list.Add(i);}}
            var seen=new HashSet<ulong>();foreach(var list in buckets.Values)for(int a=0;a<list.Count;a++)for(int b=a+1;b<list.Count;b++){int i=Math.Min(list[a],list[b]),j=Math.Max(list[a],list[b]);ulong key=((ulong)(uint)i<<32)|(uint)j;if(!seen.Add(key)||!boxes[i].Intersects(boxes[j]))continue;r.collisionCandidates++;if(Physics.ComputePenetration(all[i],all[i].transform.position,all[i].transform.rotation,all[j],all[j].transform.position,all[j].transform.rotation,out _,out float depth)&&depth>.0005f){r.penetrations++;check(false,"Penetration "+state+" "+Owner(all[i])+" <> "+Owner(all[j])+" depth="+depth);}}
        }
        static void Imported(ShipDataV5 data,Report r,Action<bool,string> check){foreach(var m in data.models){var path=ShipV5Builder.Root+"/Models/"+m.id+".fbx";var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);check(asset!=null&&File.Exists(path),"Missing actual FBX "+m.id);if(asset==null)continue;var go=UnityEngine.Object.Instantiate(asset);try{var renderers=go.GetComponentsInChildren<Renderer>();check(renderers.Length==m.parts.Length,"FBX part count "+m.id);for(int i=0;i<m.parts.Length;i++){var found=renderers.Where(v=>v.name.StartsWith(m.id+"__"+i.ToString("D2")+"_",StringComparison.Ordinal)).ToArray();check(found.Length==1,"FBX part identity "+m.id+"/"+i);if(found.Length!=1)continue;var b=ShipV5Builder.Bounds(m.parts[i]);check(Near(found[0].bounds.min,b.min,.002f)&&Near(found[0].bounds.max,b.max,.002f),"FBX scale/handedness "+m.id+"/"+i+" actual="+found[0].bounds+" expected="+b+" imported root="+go.transform.eulerAngles+" scale="+go.transform.localScale);}r.importedModels++;}finally{UnityEngine.Object.DestroyImmediate(go);}}}
        static void Navigation(GameObject root,ShipDataV5 data,Report r,Action<bool,string> check){
            var connected=new HashSet<string>{"L1_BRIDGE"};bool changed=true;while(changed){changed=false;foreach(var link in data.links){if(connected.Contains(link.a)&&connected.Add(link.b))changed=true;if(connected.Contains(link.b)&&connected.Add(link.a))changed=true;}}foreach(var zone in data.zones)check(connected.Contains(zone.id),"Disconnected source door/opening/transport graph "+zone.id);
            var sources=new List<NavMeshBuildSource>();foreach(var c in root.GetComponentsInChildren<Collider>()){var s=new NavMeshBuildSource{area=0};if(c is BoxCollider b){s.shape=NavMeshBuildSourceShape.Box;s.size=b.size;s.transform=b.transform.localToWorldMatrix*Matrix4x4.Translate(b.center);}else if(c is MeshCollider m){s.shape=NavMeshBuildSourceShape.Mesh;s.sourceObject=m.sharedMesh;s.transform=m.transform.localToWorldMatrix;}else continue;sources.Add(s);}
            var settings=NavMesh.GetSettingsCount()>0?NavMesh.GetSettingsByIndex(0):NavMesh.CreateSettings();settings.agentHeight=1.8f;settings.agentRadius=.28f;settings.agentClimb=.18f;settings.agentSlope=45;settings.overrideVoxelSize=true;settings.voxelSize=.07f;settings.overrideTileSize=true;settings.tileSize=128;
            var nav=NavMeshBuilder.BuildNavMeshData(settings,sources,new Bounds(new Vector3(32.5f,0,23.5f),new Vector3(125,40,63)),Vector3.zero,Quaternion.identity);check(nav!=null,"NavMesh build");if(nav==null)return;var handle=NavMesh.AddNavMeshData(nav);var transport=new List<NavMeshLinkInstance>();
            try {foreach(var lift in data.lifts)for(int floor=0;floor<2;floor++){bool a=NavMesh.SamplePosition(ShipV5Builder.V(lift.waypoints[floor].position)+Vector3.up*.1f,out var from,.6f,NavMesh.AllAreas);bool b=NavMesh.SamplePosition(ShipV5Builder.V(lift.waypoints[floor+1].position)+Vector3.up*.1f,out var to,.6f,NavMesh.AllAreas);check(a&&b,"TRANSPORT grounded endpoints "+lift.id+"/"+floor);if(a&&b){var link=new NavMeshLinkData{startPosition=from.position,endPosition=to.position,width=.6f,bidirectional=true,costModifier=1,area=0,agentTypeID=settings.agentTypeID};transport.Add(NavMesh.AddLink(link));r.transportLinks++;}}check(r.transportLinks==4,"Four labelled lift TRANSPORT abstractions");
                bool start=NavMesh.SamplePosition(ShipV5Builder.V(data.zones.Single(z=>z.id=="L1_BRIDGE").waypoint)+Vector3.up*.1f,out var origin,.6f,NavMesh.AllAreas);check(start,"NavMesh origin");foreach(var z in data.zones){var target=ShipV5Builder.V(z.waypoint)+Vector3.up*.1f;bool sampled=NavMesh.SamplePosition(target,out var dest,.6f,NavMesh.AllAreas);var path=new NavMeshPath();bool ok=start&&sampled&&NavMesh.CalculatePath(origin.position,dest.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;check(ok,"NavMesh unreachable (with explicit lift TRANSPORT links) "+z.id);if(ok)r.reachableZones++;r.routes.Add(new Route{zone=z.id,status=ok?"PASS_WITH_TRANSPORT":"FAIL",corners=path.corners,sampleDistance=sampled?Vector3.Distance(target,dest.position):-1});}
            }finally{foreach(var link in transport)NavMesh.RemoveLink(link);handle.Remove();UnityEngine.Object.DestroyImmediate(nav);}
        }
    }
}
